# Volume II — canonical truths, authored evidence, then deductions and tools.
# All content is original fiction. No television characters or plots are reproduced.
exec(Path('worker/content/volume2-distractors.py').read_text())
def vrecords(c,raw):
 rows=[line.split('|') for line in raw.strip().split('\n')]
 for i,r in enumerate(rows):
  # Distractors express plausible but unsupported extensions of the current record;
  # they never reveal future evidence or a future checkpoint’s explanation.
  pool=D[c['id']]; wrong=[pool[(i+k)%len(pool)] for k in (0,2,4)]
  ev(c,*r,wrong)
def vf(c,p,pid,correct,cid,wrong,exp,expid):
 opts=[(correct,cid)]+wrong
 shift=(len(c['questions'])+c['id'])%4
 final(c,p,pid,opts[shift:]+opts[:shift],(-shift)%4,exp,expid)
def tool(c,kind,stage,title,tid,intro,iid,panes,refs):
 c['tool']=dict(kind=kind,stage=stage,title=L(title,tid),intro=L(intro,iid),panes=[dict(label=L(a,b),text=L(x,y)) for a,b,x,y in panes],refs=refs)
